class EpisodeClip extends DataClass implements Insertable<EpisodeClip> {
  final int id;

  /// 所属エピソード（PodcastEpisode）
  final int episodeId;

  /// メモのタイトル（任意）
  final String? title;

  /// メモの種別（recording/file/text/url）
  final AudioMemoType memoType;

  /// 音声ファイルパス（録音・ファイルインポート時）
  final String? audioFilePath;

  /// 録音時間（秒）
  final int? durationSeconds;

  /// Whisper 文字起こし結果
  final String? transcript;

  /// ユーザーメモ・コメント
  final String? note;

  /// 抜粋テキスト（後方互換・検索用）
  final String clipText;

  /// タイムスタンプ文字列（例: "12:34"、任意）
  final String? timestampStr;

  /// 他モジュールへの送信先（'dictionary', 'thinking', 'daily' など）
  final String? sentTo;

  /// 作成日時
  final DateTime createdAt;

  /// 更新日時
  final DateTime? updatedAt;
  const EpisodeClip(
      {required this.id,
      required this.episodeId,
      this.title,
      required this.memoType,
      this.audioFilePath,
      this.durationSeconds,
      this.transcript,
      this.note,
      required this.clipText,
      this.timestampStr,
      this.sentTo,
      required this.createdAt,
      this.updatedAt});
