    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['episode_id'] = Variable<int>(episodeId);
    if (!nullToAbsent || title != null) {
      map['title'] = Variable<String>(title);
    }
    {
      map['memo_type'] =
          Variable<int>($EpisodeClipsTable.$convertermemoType.toSql(memoType));
    }
    if (!nullToAbsent || audioFilePath != null) {
      map['audio_file_path'] = Variable<String>(audioFilePath);
    }
    if (!nullToAbsent || durationSeconds != null) {
      map['duration_seconds'] = Variable<int>(durationSeconds);
    }
    if (!nullToAbsent || transcript != null) {
      map['transcript'] = Variable<String>(transcript);
    }
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    map['clip_text'] = Variable<String>(clipText);
    if (!nullToAbsent || timestampStr != null) {
      map['timestamp_str'] = Variable<String>(timestampStr);
    }
    if (!nullToAbsent || sentTo != null) {
      map['sent_to'] = Variable<String>(sentTo);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    if (!nullToAbsent || updatedAt != null) {
      map['updated_at'] = Variable<DateTime>(updatedAt);
    }
    return map;
  }

  EpisodeClipsCompanion toCompanion(bool nullToAbsent) {
    return EpisodeClipsCompanion(
